// Тикет #6a86f7d8 «פיתוח: החלפת נוסח בתוך התפילה». Опора: F-37 AC2 · S-33 AC1 (выбор текущего нусаха — без подтверждения).
import { expect } from '@wdio/globals';
import { byText, byTextContains, byLabelStartsWith, tapText, expectVisibleText, pageCounter } from '../../helpers/ui.ts';
import { openPrayer, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

describe('Смена нусаха внутри молитвы', () => {
  afterEach(async () => { await toHome(); });

  it('NS-02 Выбор текущего нусаха — без диалога #6a86f7d8 @prod-safe', async () => {
    // 1. מנחה (אשכנזי), «1 מתוך 8», секция «אשרי».
    await openPrayer('mincha_ashkenaz', 'מנחה');
    await goToPage(1, 8);
    expect(await pageCounter()).toBe('1 מתוך 8');
    await expectVisibleText('אשרי');

    // 2. Меню нусаха → «אשכנזי» (текущий).
    await (await byLabelStartsWith('בחירת נוסח')).click();
    await tapText('אשכנזי');

    // Меню закрыто, диалога нет; заголовок, счётчик и секция прежние.
    await expect(byText('ספרדי')).not.toBeDisplayed();
    await expect(byTextContains('להחליף את התפילה')).not.toBeDisplayed();
    await expect(byText('החלף')).not.toBeDisplayed();
    await expectVisibleText('מנחה (אשכנזי)');
    expect(await pageCounter()).toBe('1 מתוך 8');
    await expectVisibleText('אשרי');
  });
});
